  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `network_node_id` bigint NOT NULL,
  `capacity_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `role_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `operating_calendar_id` bigint DEFAULT NULL,
  `planned_utilization_factor` decimal(7,6) DEFAULT NULL COMMENT 'Share of the rated capacity the plan may use (0 < f <= 1); null = not stated, the full rated capacity is usable.',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE' COMMENT 'PROPOSED (a planner''s addition, out of the plan), ACTIVE or INACTIVE',
  `created_date` datetime(6) NOT NULL,
  `created_by` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `last_modified_date` datetime(6) NOT NULL,
