  `max_stocking_density` decimal(19,6) DEFAULT NULL,
  `min_fill_percent` decimal(5,2) DEFAULT NULL,
  `fill_window_days` int DEFAULT NULL,
  `single_stage` bit(1) DEFAULT NULL,
  `vehicles_per_bay_hour` decimal(18,6) DEFAULT NULL COMMENT 'Vehicles one loading bay handles per working hour (LoadingBayCapacity); null = not stated.',
