  CONSTRAINT `fk_capacity_operating_calendar` FOREIGN KEY (`operating_calendar_id`) REFERENCES `operating_calendar` (`id`),
  CONSTRAINT `fk_capacity_rate_uom` FOREIGN KEY (`rate_uom_id`) REFERENCES `uom` (`id`),
  CONSTRAINT `ck_capacity_calendar_by_basis` CHECK (((`capacity_type` not in (_utf8mb4'HOUSING',_utf8mb4'STORAGE',_utf8mb4'INCUBATION')) or (`operating_calendar_id` is null))),
  CONSTRAINT `ck_capacity_ranges` CHECK ((((`nominal_quantity` is null) or (`nominal_quantity` > 0)) and ((`min_fill_percent` is null) or ((`min_fill_percent` > 0) and (`min_fill_percent` <= 100))) and ((`fill_window_days` is null) or (`fill_window_days` >= 1)) and ((`rate_per_person_hour` is null) or (`rate_per_person_hour` > 0)) and ((`trips_per_vehicle_day` is null) or (`trips_per_vehicle_day` > 0)) and ((`vehicles_per_bay_hour` is null) or (`vehicles_per_bay_hour` > 0)))),
  CONSTRAINT `ck_capacity_role_by_type` CHECK (((`capacity_type` not in (_utf8mb4'STORAGE',_utf8mb4'LOADING_BAY')) = (`role_code` is not null))),
  CONSTRAINT `ck_capacity_status` CHECK ((`status` in (_utf8mb4'PROPOSED',_utf8mb4'ACTIVE',_utf8mb4'INACTIVE'))),
