ORAGE') and ((`nominal_quantity` is null) = (`nominal_uom_id` is null)) and (`housing_environment_type` is null) and (`min_downtime_days` is null) and (`floor_area` is null) and (`max_stocking_density` is null) and (`min_fill_percent` is null) and (`fill_window_days` is null) and (`single_stage` is null) and (`rate_per_person_hour` is null) and (`rate_uom_id` is null) and (`trips_per_vehicle_day` is null) and (`load_per_trip` is null) and (`load_uom_id` is null) and (`carrier_id` is null) and (`vehicles_per_bay_hour` is null)) or ((`capacity_type` = _utf8mb4'LABOUR') and ((`status` <> _utf8mb4'ACTIVE') or (`nominal_quantity` is not null)) and ((`nominal_quantity` is null) or (`nominal_quantity` = floor(`nominal_quantity`))) and (`nominal_uom_id` is null) and ((`rate_per_person_hour` is null) = (`rate_uom_id` is null)) and (`housing_environment_type` is null) and (`min_downtime_days` is null) and (`floor_area` is null) and (`max_stocking_density` is null) and (`min_fill_percent` is null) and (`fill_window_days` is null) and (`single_stage` is null) and (`trips_per_vehicle_day` is null) and (`temperature_class` is null) and (`space` is null) and (`load_per_trip` is null) and (`load_uom_id` is null) and (`carrier_id` is null) and (`vehicles_per_bay_hour` is null)) or ((`capacity_type` = _utf8mb4'TRANSPORT') and ((`status` <> _utf8mb4'ACTIVE') or (`nominal_quantity` is not null)) and ((`nominal_quantity` is null) or (`nominal_quantity` = floor(`nominal_quantity`))) and (`nominal_uom_id` is null) and ((`load_per_trip` is null) = (`load_uom_id` is null)) and (`housing_environment_type` is null) and (`min_downtime_days` is null) and (`floor_area` is null) and (`max_stocking_density` is null) and (`min_fill_percent` is null) and (`fill_window_days` is null) and (`single_stage` is null) and (`rate_per_person_hour` is null) and (`rate_uom_id` is null) and (`space` is null) and (`vehicles_per_bay_hour` is null)) or ((`capacity_type` = _utf8mb4'LOADING_BAY') and ((`status` <> _